import csv, json, os

out_dir = os.environ.get("AUTOMATION_OUTPUT_DIR", ".")

def load(name):
    with open(os.path.join(out_dir, name), newline="", encoding="utf-8") as f:
        return list(csv.DictReader(f))

raw = os.environ.get("AUTOMATION_INPUT", "") or "{}"
try:
    params = json.loads(raw)
except Exception:
    params = {}
try:
    n = int(params.get("topN", 3))
except (TypeError, ValueError):
    n = 3
n = max(n, 0)

merged = load("orders_a.csv") + load("orders_b.csv")
seen, deduped = set(), []
for r in merged:
    if r["order_id"] in seen:
        continue
    seen.add(r["order_id"])
    deduped.append(r)
valid = [r for r in deduped if r["status"].strip().lower() == "paid"]

top = sorted(valid, key=lambda r: float(r["amount"]), reverse=True)[:n]
data = {"top": [
    {"order_id": r["order_id"], "customer": r["customer"], "amount": float(r["amount"])}
    for r in top
]}
path = os.path.join(out_dir, "top.json")
with open(path, "w", encoding="utf-8") as f:
    json.dump(data, f, ensure_ascii=False, indent=2)
    f.write("\n")

print(f"wrote {path} (N={n})")
print(open(path, encoding="utf-8").read())

